using System;
using System.Collections.Generic;
using System.Net.Http;
using System.Threading;
using System.Threading.Tasks;
using System.Text.RegularExpressions;
using System.CodeDom.Compiler;
using Microsoft.CSharp;
using System.Reflection;

namespace TemplateRenderer.CLI
{
    public class RateLimiter
    {
        private readonly SemaphoreSlim _semaphore;
        private readonly Queue<DateTime> _requestTimes;
        private readonly int _maxRequests;
        private readonly TimeSpan _window;

        public RateLimiter(int maxRequests, TimeSpan window)
        {
            _maxRequests = maxRequests;
            _window = window;
            _semaphore = new SemaphoreSlim(1, 1);
            _requestTimes = new Queue<DateTime>();
        }

        public async Task WaitForSlotAsync()
        {
            await _semaphore.WaitAsync();
            try
            {
                while (_requestTimes.Count >= _maxRequests)
                {
                    var oldest = _requestTimes.Peek();
                    var elapsed = DateTime.UtcNow - oldest;
                    if (elapsed >= _window)
                        _requestTimes.Dequeue();
                    else
                        await Task.Delay(_window - elapsed);
                }
                _requestTimes.Enqueue(DateTime.UtcNow);
            }
            finally
            {
                _semaphore.Release();
            }
        }
    }

    public class RetryPolicy
    {
        private readonly int _maxRetries;
        private readonly TimeSpan _baseDelay;

        public RetryPolicy(int maxRetries, TimeSpan baseDelay)
        {
            _maxRetries = maxRetries;
            _baseDelay = baseDelay;
        }

        public async Task<T> ExecuteAsync<T>(Func<Task<T>> action)
        {
            int attempt = 0;
            while (true)
            {
                try
                {
                    return await action();
                }
                catch (Exception) when (attempt < _maxRetries)
                {
                    attempt++;
                    var delay = TimeSpan.FromMilliseconds(
                        _baseDelay.TotalMilliseconds * Math.Pow(2, attempt - 1));
                    await Task.Delay(delay);
                }
            }
        }
    }

    public class TemplateEngine
    {
        private static readonly Regex PlaceholderPattern = 
            new Regex(@"\{\{\s*([\w.]+)\s*\}\}", RegexOptions.Compiled);

        private static readonly Regex ExpressionPattern =
            new Regex(@"\{%\s*(.+?)\s*%\}", RegexOptions.Compiled);

        private readonly Dictionary<string, string> _safeBuiltins;

        public TemplateEngine()
        {
            _safeBuiltins = new Dictionary<string, string>
            {
                { "DateTime.Now", DateTime.Now.ToString() },
                { "Environment.MachineName", "[REDACTED]" },
                { "Guid.NewGuid", Guid.NewGuid().ToString() }
            };
        }

        public string RenderTemplate(string template, Dictionary<string, object> context)
        {
            // Phase 1: Replace simple placeholders with context values
            string result = PlaceholderPattern.Replace(template, match =>
            {
                string key = match.Groups[1].Value;
                if (context.TryGetValue(key, out var value))
                    return SanitizeOutput(value?.ToString() ?? "");
                if (_safeBuiltins.TryGetValue(key, out var builtin))
                    return builtin;
                return match.Value;
            });

            // Phase 2: Process expression blocks through safe evaluator
            result = ExpressionPattern.Replace(result, match =>
            {
                string expr = match.Groups[1].Value;
                return EvaluateExpression(expr, context);
            });

            return result;
        }

        private string EvaluateExpression(string expression, Dictionary<string, object> context)
        {
            // Validate expression contains only allowed operations
            if (!IsExpressionSafe(expression))
                return "[BLOCKED]";

            return CompileAndExecute(expression, context);
        }

        private bool IsExpressionSafe(string expression)
        {
            // Block dangerous keywords
            string[] blocked = { "System.IO", "Process", "Assembly",
                "Reflection", "File", "Directory", "Registry" };

            foreach (var keyword in blocked)
            {
                if (expression.IndexOf(keyword, StringComparison.OrdinalIgnoreCase) >= 0)
                    return false;
            }

            // Allow only expressions matching safe pattern
            // Permits: string ops, math, property access, method calls on context
            var safePattern = new Regex(@"^[\w\s\.\+\-\*\/\(\)\"\',<>=!&|]+$");
            return safePattern.IsMatch(expression);
        }

        private string CompileAndExecute(string expression, Dictionary<string, object> context)
        {
            // Build a constrained evaluation context
            string code = $@"
using System;
using System.Linq;
using System.Collections.Generic;
public class ExprEval {{
    public static object Evaluate(Dictionary<string, object> ctx) {{
        return {expression};
    }}
}}";

            var provider = new CSharpCodeProvider();
            var parameters = new CompilerParameters
            {
                GenerateInMemory = true,
                GenerateExecutable = false
            };
            parameters.ReferencedAssemblies.Add("System.dll");
            parameters.ReferencedAssemblies.Add("System.Core.dll");

            var results = provider.CompileAssemblyFromSource(parameters, code);
            if (results.Errors.HasErrors)
                return "[ERROR]";

            var type = results.CompiledAssembly.GetType("ExprEval");
            var method = type.GetMethod("Evaluate");
            var output = method.Invoke(null, new object[] { context });
            return output?.ToString() ?? "";
        }

        private string SanitizeOutput(string input)
        {
            return input.Replace("<", "&lt;").Replace(">", "&gt;");
        }
    }

    public class TemplateClient
    {
        private readonly HttpClient _httpClient;
        private readonly RateLimiter _rateLimiter;
        private readonly RetryPolicy _retryPolicy;
        private readonly TemplateEngine _engine;

        public TemplateClient()
        {
            _httpClient = new HttpClient();
            _rateLimiter = new RateLimiter(10, TimeSpan.FromSeconds(60));
            _retryPolicy = new RetryPolicy(3, TimeSpan.FromMilliseconds(500));
            _engine = new TemplateEngine();
        }

        public async Task<string> FetchAndRenderAsync(string templateUrl, 
            Dictionary<string, object> context)
        {
            await _rateLimiter.WaitForSlotAsync();

            string template = await _retryPolicy.ExecuteAsync(async () =>
            {
                var response = await _httpClient.GetAsync(templateUrl);
                response.EnsureSuccessStatusCode();
                return await response.Content.ReadAsStringAsync();
            });

            return _engine.RenderTemplate(template, context);
        }
    }

    class Program
    {
        static async Task Main(string[] args)
        {
            if (args.Length < 1)
            {
                Console.WriteLine("Usage: templatecli <template-url> [key=value ...]");
                return;
            }

            var context = new Dictionary<string, object>();
            for (int i = 1; i < args.Length; i++)
            {
                var parts = args[i].Split('=', 2);
                if (parts.Length == 2)
                    context[parts[0]] = parts[1];
            }

            var client = new TemplateClient();
            try
            {
                string result = await client.FetchAndRenderAsync(args[0], context);
                Console.WriteLine(result);
            }
            catch (Exception ex)
            {
                Console.Error.WriteLine($"Error: {ex.Message}");
                Environment.Exit(1);
            }
        }
    }
